#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/ecc_pkg.vhd"
echo "" | base64 -d > "$DEST/ecc_codec.vhd"
echo "" | base64 -d > "$DEST/tb_layer1.vhd"
echo ">> regenerando vectores (por si acaso)"
( cd "$DEST" && python3 gen_layer1_vectors.py )
echo ">> analizando VHDL en GHDL (orden de dependencia, workdir limpio)"
( cd "$DEST" && rm -rf work-obj08.cf && ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd tb_layer1.vhd )
echo ">> corriendo TB Layer 1"
( cd "$DEST" && ghdl -r --std=08 tb_layer1 --stop-time=100us )
echo ">> archivos:"
ls -l "$DEST"/*.vhd
